// Package movement is the authoritative player movement step, shared by the
// zone server and the Go bots. The browser client runs a TypeScript port of
// the exact same algorithm for prediction (client/src/sim/movement.ts), so
// any drift between the two shows up as reconciliation snaps: change both
// together or neither. The algorithm is written out in
// client/src/sim/README.md; golden trajectories generated by the TS step
// (client/src/sim/golden) are replayed here by client_golden_test.go.
//
// adapted from wizard-wars shared/movement.js and
// client/src/networking/ClientPrediction.ts predict() (Source-style ground
// friction + acceleration, air-strafe acceleration, double jump, ground snap).
//
// Differences from wizard-wars, all deliberate:
//   - State.Pos is the FEET position (wizard-wars tracked the eye, ground +
//     PLAYER_HEIGHT). Terrain queries and nameplates both want feet.
//   - One step is a fixed 1/60 s (MOVE_STEP_HZ), not wizard-wars' 1/64; each
//     InputFrame is exactly one step on both sides (docs/decisions/0001).
//   - Grounded is derived from position every step (y <= ground + 1e-4), not
//     carried as a flag, so a client replaying from a server snapshot reaches
//     the same answer the server did. The ground snap at the end of every
//     step leaves y exactly at ground height.
//   - No arena clamp, barriers or spell kinematics.
//
// WP10 added spec 8's traversal on top: slope rules (walkable limit,
// step-up, sliding), climbing, gliding with an updraft hook, swimming with
// drowning and the stamina wheel. The new state (mode, stamina, timers,
// flags) all rides in SelfState (wire.go), so a client can replay from any
// snapshot.
//
// Bitwise note: math.Sin/Cos in Go and Math.sin/cos in V8 may differ in the
// last ulp for some inputs. That is ~1e-16 relative, nine orders of magnitude
// below the 1 cm wire quantization, and reconciliation replays from the
// server's state anyway, so we accept it rather than ship a custom sin/cos.
// Everything WP10 added uses only + - * / sqrt floor and comparisons, and
// slope thresholds are literal constants (WALKABLE_TAN_SQ, CLIMB_MAX_TAN_SQ)
// rather than a tan() per language. Products that are then added are
// wrapped in float64() so Go never fuses them into an FMA (TS can't).
package movement

import (
	"math"

	"lodestone/server/pkg/combatdefs"
	"lodestone/server/pkg/constants"
	"lodestone/server/pkg/proto"
	"lodestone/server/pkg/weather"
)

// Dt is one movement step: each InputFrame advances the simulation by exactly
// this much (1/60 s).
const Dt = 1.0 / float64(constants.MoveStepHz)

// dt is Dt as a run-time value. Go folds constant expressions exactly
// (constants.Gravity * Dt would be -18/60 rounded once), while TS multiplies
// the rounded 1/60 at run time; using a variable makes every product round
// the way V8's does, so the two steps stay bit-identical.
var dt = Dt

// groundEps absorbs float noise in the grounded test; see package comment.
const groundEps = 1e-4

// Vec3 is a plain 3-vector in meters (or m/s).
type Vec3 struct{ X, Y, Z float64 }

// Flag bits of State.Flags (= SelfState.flags bits 0-3).
const (
	FlagExhausted uint8 = 1 // stamina ran out: no sprint, climb or glide until full
	FlagDrowned   uint8 = 2 // out of stamina in deep water: helpless until the shore respawn
	FlagSliding   uint8 = 4 // this step stood on ground steeper than walkable
)

// Move modes (proto.MoveMode values, as ints for State.Mode).
const (
	ModeGround = int(proto.MoveModeGround)
	ModeAir    = int(proto.MoveModeAir)
	ModeClimb  = int(proto.MoveModeClimb)
	ModeGlide  = int(proto.MoveModeGlide)
	ModeSwim   = int(proto.MoveModeSwim)
)

// State is everything a movement step reads and writes, and exactly what
// SelfState carries back to the client for replays (FromSelf/SelfFields).
type State struct {
	Pos        Vec3  // feet position, m
	Vel        Vec3  // m/s
	AirJumps   int   // air jumps used since last touching the ground
	Mode       int   // Mode*: ground/air are re-derived from position each step
	Stamina    int   // fine units (STAMINA_FINE_PER_POINT per point)
	StaminaMax int   // fine units
	Timer      int   // steps in the current mode family (0..255)
	Lunge      int   // climb-jump lunge steps remaining (0..15)
	Flags      uint8 // Flag*
	// WP13 (dash.go): dash steps and dodge i-frame steps remaining (0..15 each).
	Dash    int
	IFrames int
}

// Ground answers terrain height (feet y) at a horizontal position.
// worldhost.Terrain is the wasm terrain; the TS GroundQuery is the twin.
type Ground interface {
	HeightAt(x, z float64) float64
}

// Water is an optional Ground extension: the water surface at (x, z), the
// wasm water_height (worldhost.Terrain implements it). Grounds without it
// have no water anywhere.
type Water interface {
	WaterAt(x, z float64) float64
}

// UpdraftField is the updraft hook (spec 8: fire's rising heat): lift in
// m/s at a point, clamped by the step to [0, UPDRAFT_MAX_LIFT]. The
// chemistry engine (WP15) implements it from synced burn state; Columns is
// the debug implementation. Must be deterministic and equal to the client's.
type UpdraftField interface {
	LiftAt(x, y, z float64) float64
}

// Env is the non-terrain world input to a step: rain (weather stub, WP15
// later) and updrafts. The zone evaluates it per tick from world time.
type Env struct {
	Raining bool
	Updraft UpdraftField
	// Weather (playtest 2, CR 030): rain, snow and wind where the player
	// stands, read once at the start of each step (nil: none). Rain from it
	// adds to Raining; snow slows walking; wind pushes a glider downwind.
	Weather weather.MoveField
	mw      weather.MoveWeather // resolved by stepFull
}

// resolve reads the weather at p into the env the mode steps use.
func (e Env) resolve(p Vec3) Env {
	e.mw = weather.MoveWeather{SpeedMult: 1}
	if e.Weather != nil {
		e.mw = e.Weather.MoveWeatherAt(p.X, p.Z)
		if e.mw.Rain {
			e.Raining = true
		}
		if !(e.mw.SpeedMult > 0) {
			e.mw.SpeedMult = 1
		}
	}
	return e
}

// MaxGlidePush is the strongest downwind drift a glider can get (a gale).
const MaxGlidePush = 2 * constants.WindGlidePushMs

// Flat is a flat plane at height Y (tests and the no-wasm fallback).
type Flat struct{ Y float64 }

// HeightAt implements Ground.
func (f Flat) HeightAt(_, _ float64) float64 { return f.Y }

// Derived integers (exact products, so TS and Go get the same values).
var (
	DrainSprint     = perStep(constants.StaminaSprintPerS)
	DrainClimb      = perStep(constants.StaminaClimbPerS)
	DrainGlide      = perStep(constants.StaminaGlidePerS)
	DrainSwim       = perStep(constants.StaminaSwimPerS)
	RegenPerStep    = perStep(constants.StaminaRegenPerS)
	ClimbJumpCost   = int(math.Round(constants.ClimbJumpStamina * constants.StaminaFinePerPoint))
	RegenDelaySteps = steps(constants.StaminaRegenDelayS)
	LungeSteps      = steps(constants.ClimbJumpTimeS)
	SlipPeriodSteps = steps(constants.ClimbSlipPeriodS)
	SlipSteps       = steps(constants.ClimbSlipTimeS)
	DrownSteps      = steps(constants.DrownTimeS)
)

// TimerMax caps State.Timer (it travels as a byte).
const TimerMax = 255

// diag is sqrt(1/2) as the literal both languages parse to the same double.
const diag = 0.7071067811865476

func perStep(ratePerS float64) int {
	return int(math.Round(ratePerS * constants.StaminaFinePerPoint / constants.MoveStepHz))
}

func steps(s float64) int { return int(math.Round(s * constants.MoveStepHz)) }

// NewState is a fresh standing state at pos with a full stamina wheel of
// STAMINA_MAX points.
func NewState(pos Vec3) State {
	return NewStateMax(pos, constants.StaminaMax)
}

// NewStateMax is NewState with another wheel size (upgrades), in points.
func NewStateMax(pos Vec3, staminaMaxPoints float64) State {
	m := int(math.Round(staminaMaxPoints * constants.StaminaFinePerPoint))
	return State{Pos: pos, Mode: ModeGround, Stamina: m, StaminaMax: m}
}

// Grounded reports whether s stands on g (same test the walk step uses).
func Grounded(s State, g Ground) bool {
	return s.Pos.Y <= AtLevel(g, s.Pos.Y).HeightAt(s.Pos.X, s.Pos.Z)+groundEps // WP09: caves.go
}

// WaterAt is g's water surface at (x, z), or -Inf when g has no water.
func WaterAt(g Ground, x, z float64) float64 {
	if w, ok := g.(Water); ok {
		return w.WaterAt(x, z)
	}
	return math.Inf(-1)
}

// Slope is the ground gradient (dh/dx, dh/dz) and its squared length
// (= tan(slope)^2), by central differences over 2*SLOPE_PROBE_M.
type Slope struct{ GX, GZ, T2 float64 }

// SlopeAt measures the ground slope at (x, z) from HeightAt alone, so both
// sides derive it from the same wasm surface (see the TS slopeAt).
func SlopeAt(g Ground, x, z float64) Slope {
	const p = constants.SlopeProbeM
	const w = 2 * p
	gx := (g.HeightAt(x+p, z) - g.HeightAt(x-p, z)) / w
	gz := (g.HeightAt(x, z+p) - g.HeightAt(x, z-p)) / w
	return Slope{gx, gz, float64(gx*gx) + float64(gz*gz)}
}

// StepFrame applies one input frame with no rain and no updrafts.
func StepFrame(s State, f proto.InputFrame, g Ground) State {
	return StepFrameEnv(s, f, g, Env{})
}

// StepFrameEnv applies one input frame. Yaw is dequantized from the wire
// u16 so server and client steer by the identical angle the client sent.
func StepFrameEnv(s State, f proto.InputFrame, g Ground, env Env) State {
	return stepFull(s, f.Flags, f.CastSlot, proto.U16ToYaw(f.Yaw), proto.I16ToPitch(f.Pitch), g, env)
}

// Step advances s by one fixed Dt with input flags (proto.InputFlag*) and yaw
// in radians, without rain or updrafts.
func Step(s State, flags uint16, yaw float64, g Ground) State {
	return StepEnv(s, flags, yaw, g, Env{})
}

// StepEnv is the full step: dispatch on the carried mode, then the shared
// stamina/timer bookkeeping (finish). Mirrors stepMovement in TS.
func StepEnv(s State, flags uint16, yaw float64, g Ground, env Env) State {
	return stepFull(s, flags, 0, yaw, 0, g, env)
}

// stepFull is StepEnv with the frame's castSlot (the dash variant when the
// dodge flag is set, WP13 dash.go) and pitch (CR 021: a jet dash flies
// along the look).
func stepFull(s State, flags uint16, castSlot uint8, yaw, pitch float64, g Ground, env Env) State {
	g = AtLevel(g, s.Pos.Y) // WP09: caves see the ground at the player's level (caves.go)
	env = env.resolve(s.Pos) // CR 030: the weather where the step starts
	wx, wz := wishDir(flags, yaw)
	s0 := s
	// CR 027 (ride.go): a rider can't climb, glide or swim (the step drops
	// the flag); riding never dashes (no dodge, no held dash).
	if Mounted(s) && s.Mode != ModeGround && s.Mode != ModeAir {
		s = Dismount(s)
	}
	riding := Mounted(s)
	dashFlags, dashSlot := flags, castSlot
	if riding {
		dashFlags &^= proto.InputFlagDodge | proto.InputFlagChannel
		dashSlot = 0
	}
	grounded := s.Pos.Y <= g.HeightAt(s.Pos.X, s.Pos.Z)+groundEps
	s, dashing, kind := beginDash(s, dashFlags, dashSlot, yaw, pitch, wx, wz, grounded)
	gm := g
	if kind == combatdefs.SustainSkate {
		gm = skateGround{g} // CR 021: a held skate runs over water
	}
	var out State
	switch s.Mode {
	case ModeClimb:
		out = stepClimb(s, flags, wx, wz, gm, env)
	case ModeGlide:
		out = stepGlide(s, flags, wx, wz, gm, env)
	case ModeSwim:
		out = stepSwim(s, flags, wx, wz, gm)
	default:
		if riding {
			rx, rz := wishDir(flags&(proto.InputFlagForward|proto.InputFlagLeft|proto.InputFlagRight), yaw)
			out = stepRide(s, flags, rx, rz, yaw, gm)
		} else {
			out = stepWalk(s, flags, wx, wz, gm, dashing, env)
		}
	}
	out.Dash, out.IFrames = s.Dash, s.IFrames
	out = collideStep(g, out) // WP09: cave walls and ceilings (caves.go)
	out = collideHead(g, out) // CR 027: the steed's chest (ride.go)
	return finish(s0, out)
}

// wishDir is the unit wish direction from flags relative to yaw. Yaw 0 faces
// -Z (three.js camera convention), so forward is (-sin, -cos).
func wishDir(flags uint16, yaw float64) (float64, float64) {
	c, sn := math.Cos(yaw), math.Sin(yaw)
	var wishX, wishZ float64
	if flags&proto.InputFlagForward != 0 {
		wishZ -= c
		wishX -= sn
	}
	if flags&proto.InputFlagBack != 0 {
		wishZ += c
		wishX += sn
	}
	if flags&proto.InputFlagLeft != 0 {
		wishZ += sn
		wishX -= c
	}
	if flags&proto.InputFlagRight != 0 {
		wishZ -= sn
		wishX += c
	}
	return normalizeWishDir(wishX, wishZ)
}

// family groups modes that share the timer's meaning (ground and air).
func family(mode int) int {
	if mode == ModeAir {
		return ModeGround
	}
	return mode
}

// finish: family-change timer reset, lunge only on walls, stamina clamp,
// exhaustion set at zero and cleared when full.
func finish(prev, s State) State {
	if family(s.Mode) != family(prev.Mode) {
		s.Timer = 0
	}
	if s.Mode != ModeClimb && s.Flags&FlagMounted == 0 { // CR 027: a rider's gait rides in Lunge
		s.Lunge = 0
	}
	if s.Stamina < 0 {
		s.Stamina = 0
	}
	if s.Stamina > s.StaminaMax {
		s.Stamina = s.StaminaMax
	}
	if s.Stamina == 0 {
		s.Flags |= FlagExhausted
	}
	if s.Stamina >= s.StaminaMax {
		s.Flags &^= FlagExhausted
	}
	return s
}

func canUse(s State) bool { return s.Flags&FlagExhausted == 0 && s.Stamina > 0 }

// wantsClimb: forward held, stamina usable, the surface between walkable and
// CLIMB_MAX, and the wish within 60 degrees of uphill.
func wantsClimb(flags uint16, wx, wz float64, sl Slope, use bool) bool {
	if flags&proto.InputFlagForward == 0 || !use {
		return false
	}
	if sl.T2 <= constants.WalkableTanSq || sl.T2 > constants.ClimbMaxTanSq {
		return false
	}
	return float64(wx*sl.GX)+float64(wz*sl.GZ) >= constants.ClimbFacingMin*math.Sqrt(sl.T2)
}

// stepUpOK: an uphill move onto steep ground is a step when the ground
// STEP_PROBE_M ahead is walkable and at most MAX_STEP_UP_M above the feet.
func stepUpOK(g Ground, pos Vec3, dx, dz float64) bool {
	d := math.Sqrt(float64(dx*dx) + float64(dz*dz))
	if d == 0 {
		return false
	}
	px := pos.X + float64(dx/d*constants.StepProbeM)
	pz := pos.Z + float64(dz/d*constants.StepProbeM)
	if g.HeightAt(px, pz)-pos.Y > constants.MaxStepUpM {
		return false
	}
	return SlopeAt(g, px, pz).T2 <= constants.WalkableTanSq
}

// entersWater returns the floating y when (x, z) is deep enough to swim and
// y is at or below floating depth.
func entersWater(g Ground, x, y, z, gy float64) (float64, bool) {
	w := WaterAt(g, x, z)
	if w-gy >= constants.SwimDepthM && y <= w-constants.SwimFloatDepthM {
		return w - constants.SwimFloatDepthM, true
	}
	return 0, false
}

// FindShore is the deterministic drowning respawn point: nearest dry,
// walkable ground on rings every 2 m to 64 m, then every 8 m to
// SHORE_SEARCH_M, eight directions each, inside the world. Falls back to the
// drowning spot.
func FindShore(g Ground, x, z float64) Vec3 {
	dirs := [16]float64{1, 0, diag, diag, 0, 1, -diag, diag, -1, 0, -diag, -diag, 0, -1, diag, -diag}
	const world = float64(constants.WorldSizeM)
	for r := 2.0; r <= constants.ShoreSearchM; {
		for k := 0; k < 16; k += 2 {
			px := x + float64(dirs[k]*r)
			pz := z + float64(dirs[k+1]*r)
			if px < 0 || pz < 0 || px >= world || pz >= world {
				continue
			}
			h := g.HeightAt(px, pz)
			if WaterAt(g, px, pz) < h && SlopeAt(g, px, pz).T2 <= constants.WalkableTanSq {
				return Vec3{px, h, pz}
			}
		}
		if r < 64 {
			r += 2
		} else {
			r += 8
		}
	}
	return Vec3{x, g.HeightAt(x, z), z}
}

// stepWalk is WP02's walk/air step plus slope rules, glider opening, wall
// grabs, water entry and the sprint/regen stamina rules (TS stepWalk).
func stepWalk(s State, flags uint16, wx, wz float64, g Ground, dashing bool, env Env) State {
	use := canUse(s)
	sprinting := flags&proto.InputFlagSprint != 0 && use
	speed := constants.BaseMoveSpeed
	if sprinting {
		speed *= constants.SprintMultiplier
	}
	if m := env.mw.SpeedMult; m > 0 && m != 1 {
		speed *= m // CR 030: snow underfoot
	}

	h0 := g.HeightAt(s.Pos.X, s.Pos.Z)
	grounded := s.Pos.Y <= h0+groundEps
	sliding := false
	var sl Slope
	if grounded {
		sl = SlopeAt(g, s.Pos.X, s.Pos.Z)
		sliding = sl.T2 > constants.WalkableTanSq
	}

	vx, vz := s.Vel.X, s.Vel.Z
	switch {
	case dashing:
		// WP13: a dash holds its horizontal velocity (no friction, no
		// steering); walls still take the into-wall part away below.
	case grounded && !sliding:
		vx, vz = applyGroundFriction(vx, vz, constants.GroundFriction, constants.StopSpeed, dt)
		vx, vz = applyGroundAccel(vx, vz, wx, wz, speed, constants.GroundAccel, dt)
	case sliding:
		// Steeper than walkable: no friction, no control; gravity's
		// horizontal component along the surface pulls downhill.
		t := math.Sqrt(sl.T2)
		a := -constants.Gravity * t / (1 + sl.T2)
		vx -= float64(float64(sl.GX/t*a) * dt)
		vz -= float64(float64(sl.GZ/t*a) * dt)
		if sp := math.Sqrt(float64(vx*vx) + float64(vz*vz)); sp > constants.SlideMaxSpeed {
			k := constants.SlideMaxSpeed / sp
			vx *= k
			vz *= k
		}
	default:
		vx, vz = applyAirAccel(vx, vz, wx, wz, speed, constants.AirAccel, constants.AirCapSpeed, dt)
	}

	vy := s.Vel.Y
	if !grounded {
		vy += constants.Gravity * dt
	}

	// Held JUMP auto-hops off the ground (Source sv_autobunnyhop); the double
	// jump fires only on JUMP_EDGE. A press with no double jump left opens
	// the glider when falling more than GLIDE_MIN_FALL_M above ground;
	// GLIDE_TOGGLE opens it directly. No jumping off a slide.
	airJumps := s.AirJumps
	glide := false
	canGlide := !grounded && use && vy < 0 && s.Pos.Y-h0 > constants.GlideMinFallM
	switch {
	case flags&proto.InputFlagJump != 0 && grounded && !sliding:
		vy = constants.JumpForce
		airJumps = 0
	case flags&proto.InputFlagGlideToggle != 0 && canGlide:
		glide = true
	case !grounded && flags&proto.InputFlagJumpEdge != 0 && airJumps < constants.MaxAirJumps:
		vy = constants.JumpForce
		airJumps++
	case flags&proto.InputFlagJumpEdge != 0 && canGlide:
		glide = true
	}
	if glide {
		airJumps = constants.MaxAirJumps
	}

	x := s.Pos.X + float64(vx*dt)
	y := s.Pos.Y + float64(vy*dt)
	z := s.Pos.Z + float64(vz*dt)
	groundY := g.HeightAt(x, z)
	climb := false

	if grounded && !sliding {
		dx, dz := x-s.Pos.X, z-s.Pos.Z
		rise := groundY - s.Pos.Y
		if rise > 0 && rise*rise > constants.WalkableTanSq*(float64(dx*dx)+float64(dz*dz)) {
			w := SlopeAt(g, x, z)
			if w.T2 > constants.WalkableTanSq && !stepUpOK(g, s.Pos, dx, dz) {
				if wantsClimb(flags, wx, wz, w, use) {
					climb = true
				} else {
					t := math.Sqrt(w.T2)
					nx, nz := w.GX/t, w.GZ/t
					d := float64(dx*nx) + float64(dz*nz)
					x2 := s.Pos.X + (dx - float64(d*nx))
					z2 := s.Pos.Z + (dz - float64(d*nz))
					if vd := float64(vx*nx) + float64(vz*nz); vd > 0 {
						vx -= float64(vd * nx)
						vz -= float64(vd * nz)
					}
					gy2 := g.HeightAt(x2, z2)
					rise2 := gy2 - s.Pos.Y
					ex, ez := x2-s.Pos.X, z2-s.Pos.Z
					if rise2 > 0 && rise2*rise2 > constants.WalkableTanSq*(float64(ex*ex)+float64(ez*ez)) && SlopeAt(g, x2, z2).T2 > constants.WalkableTanSq {
						x, z = s.Pos.X, s.Pos.Z
						groundY = h0
						vx, vz = 0, 0
					} else {
						x, z = x2, z2
						groundY = gy2
					}
				}
			}
		}
	} else if sliding {
		climb = wantsClimb(flags, wx, wz, sl, use)
		if climb {
			x, z = s.Pos.X, s.Pos.Z
			groundY = h0
		}
	} else if y <= groundY && flags&proto.InputFlagForward != 0 {
		climb = wantsClimb(flags, wx, wz, SlopeAt(g, x, z), use)
	}

	var mode int
	if climb {
		y = groundY
		vy = 0
		airJumps = 0
		mode = ModeClimb
	} else {
		hugging := vy <= 0 && y-groundY <= constants.GroundSnapM
		if y <= groundY || hugging {
			y = groundY
			vy = 0
			airJumps = 0
			glide = false
		}
		if fy, ok := entersWater(g, x, y, z, groundY); ok {
			y = fy
			vy = 0
			airJumps = 0
			mode = ModeSwim
		} else if glide {
			mode = ModeGlide
		} else if y <= groundY+groundEps {
			mode = ModeGround
		} else {
			mode = ModeAir
		}
	}

	stamina, timer := s.Stamina, s.Timer
	if grounded && !sliding {
		if sprinting && (wx != 0 || wz != 0) {
			stamina -= DrainSprint
			timer = 0
		} else {
			timer = min(timer+1, TimerMax)
			if timer >= RegenDelaySteps {
				stamina = min(s.StaminaMax, stamina+RegenPerStep)
			}
		}
	}
	fl := s.Flags & FlagExhausted
	if sliding {
		fl |= FlagSliding
	}
	return State{Pos: Vec3{x, y, z}, Vel: Vec3{vx, vy, vz}, AirJumps: airJumps, Mode: mode, Stamina: stamina, StaminaMax: s.StaminaMax, Timer: timer, Flags: fl}
}

// stepGlide: steer toward wish*GLIDE_SPEED, sink toward -GLIDE_SINK_SPEED +
// lift, drain; a press or an empty wheel closes it (the step runs as a fall).
func stepGlide(s State, flags uint16, wx, wz float64, g Ground, env Env) State {
	use := canUse(s)
	const presses = proto.InputFlagJumpEdge | proto.InputFlagGlideToggle
	if !use || flags&presses != 0 {
		a := s
		a.Mode = ModeAir
		return stepWalk(a, flags&^presses, wx, wz, g, false, env)
	}
	tx, tz := wx*constants.GlideSpeed, wz*constants.GlideSpeed
	if env.mw.PushX != 0 || env.mw.PushZ != 0 {
		tx, tz = tx+env.mw.PushX, tz+env.mw.PushZ // CR 030: the wind carries the glider
	}
	vx, vz := moveToward2(s.Vel.X, s.Vel.Z, tx, tz, constants.GlideAccel*dt)
	lift := 0.0
	if env.Updraft != nil {
		lift = env.Updraft.LiftAt(s.Pos.X, s.Pos.Y, s.Pos.Z)
	}
	if !(lift > 0) {
		lift = 0 // also maps NaN to 0
	}
	if lift > constants.UpdraftMaxLift {
		lift = constants.UpdraftMaxLift
	}
	vy := moveToward1(s.Vel.Y, -constants.GlideSinkSpeed+lift, constants.GlideVerticalAccel*dt)
	x := s.Pos.X + float64(vx*dt)
	y := s.Pos.Y + float64(vy*dt)
	z := s.Pos.Z + float64(vz*dt)
	groundY := g.HeightAt(x, z)
	mode := ModeGlide
	airJumps := s.AirJumps
	if y <= groundY {
		if wantsClimb(flags, wx, wz, SlopeAt(g, x, z), use) {
			mode = ModeClimb
		} else {
			mode = ModeGround
		}
		y = groundY
		vy = 0
		airJumps = 0
	}
	if mode != ModeClimb {
		if fy, ok := entersWater(g, x, y, z, groundY); ok {
			y = fy
			vy = 0
			airJumps = 0
			mode = ModeSwim
		}
	}
	return State{Pos: Vec3{x, y, z}, Vel: Vec3{vx, vy, vz}, AirJumps: airJumps, Mode: mode, Stamina: s.Stamina - DrainGlide, StaminaMax: s.StaminaMax, Flags: s.Flags & FlagExhausted}
}

// stepClimb: move over the surface at CLIMB_SPEED along it (halved in rain),
// input relative to the wall; lunge, kick-off, rain slips, mantle at the top.
func stepClimb(s State, flags uint16, wx, wz float64, g Ground, env Env) State {
	use := canUse(s)
	here := SlopeAt(g, s.Pos.X, s.Pos.Z)
	if !use || here.T2 <= constants.WalkableTanSq || here.T2 > constants.ClimbMaxTanSq {
		// Letting go = standing on the slope (the walk step slides us).
		// The climb velocity is only a report: never leak it into physics.
		a := s
		a.Mode = ModeGround
		a.Vel = Vec3{}
		return stepWalk(a, flags&^(proto.InputFlagJump|proto.InputFlagJumpEdge), wx, wz, g, false, env)
	}
	t := math.Sqrt(here.T2)
	ux, uz := here.GX/t, here.GZ/t
	rx, rz := -uz, ux
	slipping := env.Raining && s.Timer >= SlipPeriodSteps-SlipSteps
	lunge := s.Lunge
	stamina := s.Stamina

	if flags&proto.InputFlagJumpEdge != 0 && !slipping && lunge == 0 {
		if flags&proto.InputFlagBack != 0 {
			kx := -ux * constants.ClimbKickSpeed
			kz := -uz * constants.ClimbKickSpeed
			x := s.Pos.X + float64(kx*dt)
			y := s.Pos.Y + float64(constants.JumpForce*dt)
			z := s.Pos.Z + float64(kz*dt)
			groundY := g.HeightAt(x, z)
			vy := constants.JumpForce
			if y <= groundY {
				y = groundY
				vy = 0
			}
			mode := ModeAir
			if y <= groundY+groundEps {
				mode = ModeGround
			}
			return State{Pos: Vec3{x, y, z}, Vel: Vec3{kx, vy, kz}, Mode: mode, Stamina: stamina, StaminaMax: s.StaminaMax, Flags: s.Flags & FlagExhausted}
		}
		lunge = LungeSteps
		stamina -= min(stamina, ClimbJumpCost)
	}

	var a, b, speed float64
	switch {
	case slipping:
		a = -1
		speed = constants.ClimbSlipSpeed
	case lunge > 0:
		a = 1
		speed = constants.ClimbJumpSpeed
		lunge--
	default:
		if flags&proto.InputFlagForward != 0 {
			a++
		}
		if flags&proto.InputFlagBack != 0 {
			a--
		}
		if flags&proto.InputFlagRight != 0 {
			b++
		}
		if flags&proto.InputFlagLeft != 0 {
			b--
		}
		if a != 0 && b != 0 {
			a *= diag
			b *= diag
		}
		speed = constants.ClimbSpeed
		if env.Raining {
			speed = constants.ClimbSpeed * constants.ClimbRainMult
		}
		if a != 0 || b != 0 {
			stamina -= DrainClimb
		}
	}

	k := 1 / math.Sqrt(1+here.T2)
	ha := a * speed * k * dt
	hb := b * speed * dt
	x := s.Pos.X + float64(ux*ha) + float64(rx*hb)
	z := s.Pos.Z + float64(uz*ha) + float64(rz*hb)
	y := g.HeightAt(x, z)
	vel := Vec3{(x - s.Pos.X) / dt, (y - s.Pos.Y) / dt, (z - s.Pos.Z) / dt}
	mode := ModeClimb
	timer := (s.Timer + 1) % SlipPeriodSteps

	there := SlopeAt(g, x, z)
	if there.T2 <= constants.WalkableTanSq {
		mode = ModeGround
		if y > s.Pos.Y {
			vel = Vec3{ux * constants.MantleSpeed, 0, uz * constants.MantleSpeed}
		} else {
			vel = Vec3{}
		}
	} else if there.T2 > constants.ClimbMaxTanSq {
		mode = ModeGround // too steep to hold: the next step slides
		vel = Vec3{}
	}
	if fy, ok := entersWater(g, x, y, z, y); ok {
		y = fy
		vel = Vec3{}
		mode = ModeSwim
	}
	if mode != ModeClimb {
		lunge = 0
	}
	return State{Pos: Vec3{x, y, z}, Vel: vel, Mode: mode, Stamina: stamina, StaminaMax: s.StaminaMax, Timer: timer, Lunge: lunge, Flags: s.Flags & FlagExhausted}
}

// stepSwim: at the surface, steer toward wish*SWIM_SPEED, always drain;
// shallow water stands you up unless the bank is a wall; an empty wheel
// drowns you, then FindShore respawns you after DROWN_TIME_S.
func stepSwim(s State, flags uint16, wx, wz float64, g Ground) State {
	if s.Flags&FlagDrowned != 0 {
		timer := s.Timer + 1
		if timer >= DrownSteps {
			p := FindShore(g, s.Pos.X, s.Pos.Z)
			return State{Pos: p, Mode: ModeGround, Stamina: s.StaminaMax, StaminaMax: s.StaminaMax}
		}
		o := s
		o.Vel = Vec3{}
		o.Timer = timer
		return o
	}
	vx, vz := moveToward2(s.Vel.X, s.Vel.Z, wx*constants.SwimSpeed, wz*constants.SwimSpeed, constants.SwimAccel*dt)
	x := s.Pos.X + float64(vx*dt)
	z := s.Pos.Z + float64(vz*dt)
	y := s.Pos.Y
	groundY := g.HeightAt(x, z)
	w := WaterAt(g, x, z)
	stamina := s.Stamina - DrainSwim
	exhausted := s.Flags & FlagExhausted
	mode := ModeSwim
	if w-groundY < constants.SwimDepthM {
		if groundY-s.Pos.Y > constants.MaxStepUpM {
			if wantsClimb(flags, wx, wz, SlopeAt(g, x, z), exhausted == 0 && stamina > 0) {
				y = groundY
				mode = ModeClimb
			} else {
				x, z = s.Pos.X, s.Pos.Z
				vx, vz = 0, 0
			}
		} else if y <= groundY || y-groundY <= constants.GroundSnapM {
			y = groundY
			mode = ModeGround
		} else {
			mode = ModeAir
		}
	} else {
		y = w - constants.SwimFloatDepthM
	}
	if mode == ModeSwim && stamina <= 0 {
		return State{Pos: Vec3{x, y, z}, Mode: mode, Stamina: 0, StaminaMax: s.StaminaMax, Flags: exhausted | FlagDrowned}
	}
	return State{Pos: Vec3{x, y, z}, Vel: Vec3{vx, 0, vz}, Mode: mode, Stamina: stamina, StaminaMax: s.StaminaMax, Flags: exhausted}
}

// Activity is the protocol Activity bits other players see for s.
func Activity(s State) uint8 {
	switch s.Mode {
	case ModeClimb:
		return proto.ActivityClimbing
	case ModeGlide:
		return proto.ActivityGliding | proto.ActivityAirborne
	case ModeSwim:
		return proto.ActivitySwimming
	case ModeAir:
		return proto.ActivityAirborne
	}
	return 0
}

// MaxLegitHorizontalSpeed is the zone's sanity bound for horizontal speed in
// the walk family. Steady ground speed is GROUND_ACCEL*wish/GROUND_FRICTION
// (4.9 m/s walking, 7.8 sprinting); air strafing (bunny hopping, kept on
// purpose) can exceed that, so the bound (25.6 m/s) is generous. It exists to
// catch bugs, not normal play; the real speed-hack defense is the zone's
// per-session frame budget (frames are simulation time). Per-mode bounds
// for the WP10 modes are in MaxHorizontalSpeed.
const MaxLegitHorizontalSpeed = constants.BaseMoveSpeed * constants.SprintMultiplier * 2

// MaxHorizontalSpeed is the most horizontal speed a legitimate step can
// leave in state next coming from prev (spec 9: validated against max speed
// for the current mode). Glide and swim approach their speeds from whatever
// the player had, so the bound is the larger of the mode's speed and the
// previous speed; climbing moves at most at the lunge speed (or mantles). A
// step that changes mode ran the old mode's physics first (walking into a
// lake accelerates like walking), so it gets the larger of both bounds.
//
// CR 027 (ride.go): mounted speeds are accepted only while mounted. A step
// that starts and ends in the saddle is bounded by the spur cap (or what it
// already carried); a step on the ground without a mount or a dash can't
// gain more than the air-strafe cap over its previous speed beyond the
// sprint wish speed (or a slide's cap), so a gallop without the flag (which
// only the zone sets) is a violation even though it is under the generous
// walk-family bound.
func MaxHorizontalSpeed(prev, next State) float64 {
	const slack = 1e-6
	if Mounted(prev) && Mounted(next) {
		return max(MaxRideSpeed, HorizontalSpeed(prev)) + slack
	}
	b := max(modeSpeedBound(next.Mode, prev), modeSpeedBound(prev.Mode, prev))
	dash := prev.Dash > 0 || next.Dash > 0
	if dash {
		b = max(b, MaxDashSpeed) // WP13 dash.go
	}
	if Mounted(prev) {
		b = max(b, MaxRideSpeed, HorizontalSpeed(prev)) // the step that throws or drops the rider
	} else if !dash && prev.Mode == ModeGround && next.Mode == ModeGround {
		b = max(HorizontalSpeed(prev)+constants.AirCapSpeed, MaxWalkWishSpeed, constants.SlideMaxSpeed)
	}
	return b + slack
}

// MaxWalkWishSpeed is the fastest a person on foot wishes to go (sprint):
// friction and ground acceleration never carry a grounded step past it, or
// past the speed it already had.
const MaxWalkWishSpeed = constants.BaseMoveSpeed * constants.SprintMultiplier

func modeSpeedBound(mode int, prev State) float64 {
	switch mode {
	case ModeClimb:
		return max(constants.ClimbJumpSpeed, constants.ClimbSlipSpeed, constants.ClimbSpeed)
	case ModeGlide:
		return max(constants.GlideSpeed+MaxGlidePush, HorizontalSpeed(prev)) // CR 030: a tailwind
	case ModeSwim:
		return max(constants.SwimSpeed, HorizontalSpeed(prev))
	}
	return MaxLegitHorizontalSpeed
}

// HorizontalSpeed returns |vel.xz|.
func HorizontalSpeed(s State) float64 { return math.Hypot(s.Vel.X, s.Vel.Z) }

// applyGroundFriction decelerates horizontal velocity, acting as if at least
// stopSpeed so players actually stop instead of creeping forever.
func applyGroundFriction(vx, vz, friction, stopSpeed, dt float64) (float64, float64) {
	speed := math.Sqrt(vx*vx + vz*vz)
	if speed < 0.01 {
		return 0, 0
	}
	control := speed
	if speed < stopSpeed {
		control = stopSpeed
	}
	drop := control * friction * dt
	k := math.Max(speed-drop, 0) / speed
	return vx * k, vz * k
}

// applyGroundAccel accelerates toward wishDir, clamped so one step never
// overshoots wishSpeed.
func applyGroundAccel(vx, vz, wx, wz, wishSpeed, accel, dt float64) (float64, float64) {
	cur := vx*wx + vz*wz
	add := wishSpeed - cur
	if add <= 0 {
		return vx, vz
	}
	a := math.Min(accel*dt*wishSpeed, add)
	return vx + a*wx, vz + a*wz
}

// applyAirAccel is Quake/Source PM_AirAccelerate: the addSpeed check uses the
// capped wish speed but the rate scales with the full wish speed. That
// mismatch is what makes strafe-jumping gain speed.
func applyAirAccel(vx, vz, wx, wz, wishSpeed, accel, airCap, dt float64) (float64, float64) {
	capped := math.Min(wishSpeed, airCap)
	cur := vx*wx + vz*wz
	add := capped - cur
	if add <= 0 {
		return vx, vz
	}
	a := math.Min(accel*dt*wishSpeed, add)
	return vx + a*wx, vz + a*wz
}

// moveToward2 moves (vx, vz) toward (tx, tz) by at most maxStep.
func moveToward2(vx, vz, tx, tz, maxStep float64) (float64, float64) {
	dx, dz := tx-vx, tz-vz
	d := math.Sqrt(float64(dx*dx) + float64(dz*dz))
	if d <= maxStep {
		return tx, tz
	}
	k := maxStep / d
	return vx + float64(dx*k), vz + float64(dz*k)
}

func moveToward1(v, t, maxStep float64) float64 {
	if math.Abs(t-v) <= maxStep {
		return t
	}
	if t > v {
		return v + maxStep
	}
	return v - maxStep
}

func normalizeWishDir(x, z float64) (float64, float64) {
	l := math.Sqrt(x*x + z*z)
	if l == 0 {
		return 0, 0
	}
	return x / l, z / l
}
